passes.source:
precision highp float;

uniform vec2 iResolution;
uniform float iTime;

// One uniform per control, named u_<key>.
uniform float u_speed;
uniform float u_blend;
uniform vec3 u_baseColor;
uniform vec3 u_lightColor;

#include "sdf.glsl"

// The whole scene as one distance: a sphere melting into a rounded box, over a floor.
float scene(vec3 p) {
  float t = iTime * u_speed;
  vec3 q = p - vec3(0.0, 0.08 * sin(t * 2.0), 0.0);
  float sphere = sdSphere(q - vec3(0.5 * sin(t), 0.0, 0.0), 0.42);
  float box = sdRoundBox(q, vec3(0.32), 0.06);
  return min(smoothUnion(sphere, box, u_blend), p.y + 0.6);
}

// The surface normal is the gradient of the distance, by central differences.
vec3 normalAt(vec3 p) {
  vec2 e = vec2(0.001, 0.0);
  return normalize(vec3(
    scene(p + e.xyy) - scene(p - e.xyy),
    scene(p + e.yxy) - scene(p - e.yxy),
    scene(p + e.yyx) - scene(p - e.yyx)
  ));
}

// March towards the light: the closest miss along the way darkens the point.
float softShadow(vec3 origin, vec3 toLight) {
  float shade = 1.0;
  float travelled = 0.02;
  for (int i = 0; i < 32; i++) {
    float d = scene(origin + toLight * travelled);
    shade = min(shade, 8.0 * d / travelled);
    travelled += clamp(d, 0.02, 0.25);
    if (shade < 0.001 || travelled > 6.0) break;
  }
  return clamp(shade, 0.0, 1.0);
}

void main() {
  vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution) / iResolution.y;
  vec3 origin = vec3(0.0, 0.35, 2.6);
  vec3 ray = normalize(vec3(uv, -1.6));

  // Sphere tracing: step by the distance to the nearest surface until it is tiny.
  float travelled = 0.0;
  bool hit = false;
  for (int i = 0; i < 96; i++) {
    float d = scene(origin + ray * travelled);
    if (d < 0.001) {
      hit = true;
      break;
    }
    travelled += d;
    if (travelled > 12.0) break;
  }

  vec3 sky = mix(vec3(0.04, 0.05, 0.08), vec3(0.16, 0.19, 0.27), clamp(uv.y + 0.5, 0.0, 1.0));
  vec3 color = sky;
  if (hit) {
    vec3 p = origin + ray * travelled;
    vec3 n = normalAt(p);
    vec3 toLight = normalize(vec3(0.6, 0.8, 0.35));
    float diffuse = max(dot(n, toLight), 0.0) * softShadow(p + n * 0.002, toLight);
    float rim = pow(1.0 - max(dot(n, -ray), 0.0), 3.0);
    float checker = mod(floor(p.x * 2.0) + floor(p.z * 2.0), 2.0);
    vec3 albedo = p.y < -0.59 ? vec3(0.22 + 0.08 * checker) : u_baseColor;
    color = albedo * (0.12 + diffuse * u_lightColor) + rim * 0.25 * u_lightColor;
    color = mix(color, sky, 1.0 - exp(-0.015 * travelled * travelled));
  }

  // Lighting is computed in linear light; the screen expects gamma-encoded values.
  gl_FragColor = vec4(pow(color, vec3(0.4545)), 1.0);
}

