// Signed distance functions: negative inside a shape, zero on it, positive outside.
// Included by the Image pass with  #include "sdf.glsl"

float sdSphere(vec3 p, float radius) {
  return length(p) - radius;
}

float sdRoundBox(vec3 p, vec3 halfSize, float rounding) {
  vec3 q = abs(p) - halfSize + rounding;
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0) - rounding;
}

// A union that melts two shapes together; k is how far the blend reaches.
float smoothUnion(float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (b - a) / max(k, 0.0001), 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}
